import type { Chapter } from '../../schema';
import { choice, fill, order } from '../helpers';
import { problem } from './h';

const GRAPH = `class GNode { constructor(val) { this.val = val; this.neighbors = []; } }
// adj[i] lists the neighbours of node i + 1 (1-indexed, undirected). Returns node 1 or null.
const buildGraph = (adj) => { const ns = adj.map((_, i) => new GNode(i + 1)); adj.forEach((nb, i) => { ns[i].neighbors = nb.map((v) => ns[v - 1]); }); return ns[0] ?? null; };
const graphToAdj = (node) => { if (!node) return []; const seen = new Map(), q = [node]; seen.set(node.val, node); while (q.length) { const n = q.shift(); for (const m of n.neighbors) if (!seen.has(m.val)) { seen.set(m.val, m); q.push(m); } } return [...seen.keys()].sort((a, b) => a - b).map((v) => seen.get(v).neighbors.map((m) => m.val)); };`;

