      analogy: "Spotting islands from an aeroplane: each time you see land you have not marked yet, you count a new island and colour the whole island in so you do not count it again.",
      approach: "Loop over every cell. On a '1', increment the count and run DFS from it, turning every connected '1' into '0' (visited). Each cell is visited a constant number of times, so the total is O(rows × cols).",
      brute: ['BFS flood fill with a queue', "function numIslands(grid) {\n  const g = grid.map((r) => [...r]), R = g.length, C = g[0].length;\n  let count = 0;\n  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) {\n    if (g[r][c] !== '1') continue;\n    count++;\n    const q = [[r, c]]; g[r][c] = '0';\n    while (q.length) {\n      const [x, y] = q.shift();\n      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {\n        const a = x + dx, b = y + dy;\n        if (a >= 0 && b >= 0 && a < R && b < C && g[a][b] === '1') { g[a][b] = '0'; q.push([a, b]); }\n      }\n    }\n  }\n  return count;\n}"],
      best: ['DFS flood fill', "function numIslands(grid) {\n  const g = grid.map((r) => [...r]), R = g.length, C = g[0].length;\n  const sink = (r, c) => {\n    if (r < 0 || c < 0 || r >= R || c >= C || g[r][c] !== '1') return;\n    g[r][c] = '0';\n    sink(r + 1, c); sink(r - 1, c); sink(r, c + 1); sink(r, c - 1);\n  };\n  let count = 0;\n  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) if (g[r][c] === '1') { count++; sink(r, c); }\n  return count;\n}\nconsole.log(numIslands(['11000', '11000', '00100', '00011']));", '3'],
