      ex: { prompt: 'Write numIslands(grid) where grid is an array of strings of "1" (land) and "0" (water). Return the number of islands (4-directionally connected land).', py: "def numIslands(grid):\n    g = [list(row) for row in grid]\n    R, C = len(g), len(g[0])\n    def sink(r, c):\n        if r < 0 or c < 0 or r >= R or c >= C or g[r][c] != '1':\n            return\n        g[r][c] = '0'\n        sink(r + 1, c); sink(r - 1, c); sink(r, c + 1); sink(r, c - 1)\n    count = 0\n    for r in range(R):\n        for c in range(C):\n            if g[r][c] == '1':\n                count += 1\n                sink(r, c)\n    return count\n", sig: "(string[] grid) -> int", java: "class Solution {\n    public int numIslands(String[] grid) {\n        char[][] g = new char[grid.length][];\n        for (int r = 0; r < grid.length; r++) g[r] = grid[r].toCharArray();\n        int count = 0;\n        for (int r = 0; r < g.length; r++)\n            for (int c = 0; c < g[0].length; c++)\n                if (g[r][c] == '1') { count++; sink(g, r, c); }\n        return count;\n    }\n    private void sink(char[][] g, int r, int c) {\n        if (r < 0 || c < 0 || r >= g.length || c >= g[0].length || g[r][c] != '1') return;\n        g[r][c] = '0';\n        sink(g, r + 1, c);\n        sink(g, r - 1, c);\n        sink(g, r, c + 1);\n        sink(g, r, c - 1);\n    }\n}\n", cpp: "class Solution {\npublic:\n    int numIslands(vector<string>& grid) {\n        int count = 0;\n        for (int r = 0; r < (int)grid.size(); r++)\n            for (int c = 0; c < (int)grid[0].size(); c++)\n                if (grid[r][c] == '1') { count++; sink(grid, r, c); }\n        return count;\n    }\nprivate:\n    void sink(vector<string>& g, int r, int c) {\n        if (r < 0 || c < 0 || r >= (int)g.size() || c >= (int)g[0].size() || g[r][c] != '1') return;\n        g[r][c] = '0';\n        sink(g, r + 1, c);\n        sink(g, r - 1, c);\n        sink(g, r, c + 1);\n        sink(g, r, c - 1);\n    }\n};\n", fn: 'numIslands', params: 'grid', cases: [{ args: [['11110', '11010', '11000', '00000']], expect: 1 }, { args: [['11000', '11000', '00100', '00011']], expect: 3 }, { args: [['0']], expect: 0 }, { args: [['101', '010', '101']], expect: 5 }], solution: "function numIslands(grid){const g=grid.map(r=>[...r]),R=g.length,C=g[0].length;const s=(r,c)=>{if(r<0||c<0||r>=R||c>=C||g[r][c]!=='1')return;g[r][c]='0';s(r+1,c);s(r-1,c);s(r,c+1);s(r,c-1)};let n=0;for(let r=0;r<R;r++)for(let c=0;c<C;c++)if(g[r][c]==='1'){n++;s(r,c)}return n}", hint: 'Count each new land cell, then sink its whole island.' },
