      best: ['DFS returning area', "function maxAreaOfIsland(grid) {\n  const g = grid.map((r) => [...r]), R = g.length, C = g[0].length;\n  const area = (r, c) => {\n    if (r < 0 || c < 0 || r >= R || c >= C || g[r][c] !== 1) return 0;\n    g[r][c] = 0;\n    return 1 + area(r + 1, c) + area(r - 1, c) + area(r, c + 1) + area(r, c - 1);\n  };\n  let best = 0;\n  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) best = Math.max(best, area(r, c));\n  return best;\n}\nconsole.log(maxAreaOfIsland([[1, 1, 0], [1, 0, 0], [0, 0, 1]]));", '3'],
